script:
frappe.ui.form.on("Item", {
    item_group: function(frm) {
        if (frm.doc.item_group && frm.doc.__islocal) {
            frappe.db.get_value("Item Group", frm.doc.item_group, "custom_naming_series")
                .then(r => {
                    if (r.message && r.message.custom_naming_series) {
                        frm.set_value("naming_series", r.message.custom_naming_series);
                    }
                });
        }
    }
});
